// What a list remembers. The filters a person last used on a list (its search words and its status)
// are kept for the browser tab in `sessionStorage`, per aggregate, and applied when the list is opened
// again with none named. Naming any of them, even to empty them, replaces what was kept; the Clear
// link forgets it. Storage can be blocked or full, so every use of it is allowed to fail and the list
// is then simply unfiltered.

const KEPT = ["_q", "_status"];

/** Whether the address names any filter or page of its own. */
const named = (params) => ["_q", "_status", "_page"].some((key) => params.has(key));

export function rememberFilters() {
  const form = document.querySelector("form[data-list-filters]");
  if (!form) return;
  const key = `editor:list:${form.dataset.list}`;
  const params = new URLSearchParams(window.location.search);
  document.querySelector("[data-clear-filters]")?.addEventListener("click", () => {
    try {
      window.sessionStorage.removeItem(key);
    } catch (error) {
      /* storage is blocked: nothing was kept to forget */
    }
  });
  try {
    if (params.has("_q") || params.has("_status")) {
      const kept = Object.fromEntries(KEPT.map((name) => [name, params.get(name) ?? ""]));
      if (KEPT.every((name) => kept[name] === "")) window.sessionStorage.removeItem(key);
      else window.sessionStorage.setItem(key, JSON.stringify(kept));
      return;
    }
    const saved = named(params) ? null : JSON.parse(window.sessionStorage.getItem(key) ?? "null");
    if (!saved) return;
    for (const name of KEPT) if (typeof saved[name] === "string" && saved[name] !== "") params.set(name, saved[name]);
    window.location.replace(`${window.location.pathname}?${params.toString()}`);
  } catch (error) {
    /* storage is blocked or holds something that is not ours: the list stays as the address names it */
  }
}
